package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import org.json.*;import com.insight.quantlife.*;import java.io.*;import java.util.regex.*;

/** Second user-authorized public document. Does not alter the remote document. */
public class FeishuSecondDocumentTest extends DocumentEditorTest {
 String TOKEN="",URL="",firstToken="";
 @Override public void onCreate(Bundle b){URL=b==null?"":b.getString("docUrl","");TOKEN=android.net.Uri.parse(URL).getLastPathSegment();firstToken=android.net.Uri.parse(b==null?"":b.getString("firstUrl","")).getLastPathSegment();super.onCreate(b);}
 JSONObject source(String token)throws Exception{JSONArray rows=records();for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i),meta=r.optJSONObject("feishuSource");if(meta!=null&&meta.optString("documentId").equals(token))return r;}return null;}
 @Override public void onStart(){Bundle result=new Bundle();try{
  if(!Build.HARDWARE.matches("ranchu|goldfish"))throw new Exception("This integration test is restricted to a disposable Android emulator");
  if(URL.isEmpty()||TOKEN==null||firstToken==null)throw new Exception("Pass live test documents with -e docUrl and -e firstUrl; personal links are not source fixtures");
  h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{};FeishuUI.close();document.querySelector('[data-page=chat]').click()");
  JSONObject first=source(firstToken);check(first!=null,"First imported Scrapy note remains present before second import");String before=first.toString();
  JSONObject old=source(TOKEN);if(old!=null)h.call("applyRecordAction",new JSONObject().put("kind","delete").put("recordId",old.getString("id")).put("expectedVersion",old.getLong("updatedAt")));
  JSONObject live=(JSONObject)h.call("feishuRead",new JSONObject().put("url",URL+"?from=from_copylink"));String note=live.getString("note");
  check(live.getString("title").equals("LangChain框架入门概念"),"Second real title is LangChain framework introduction");check(live.getString("documentCreatedDate").equals("2026-03-27"),"Second real document creation date is read independently");check(live.getInt("blocks")==53&&note.length()>20000,"All 53 body blocks of long document traversed without 6000-character truncation");check(note.contains("走进LangChain")&&note.contains("将用户问题、输出结果还有中间思考和执行过程打印出来。"),"Both beginning and final paragraph retained");
  File sourceFile=new File(getTargetContext().getFilesDir(),"qa/feishu-second-source.json");String raw;try(InputStream in=new FileInputStream(sourceFile);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);raw=new String(out.toByteArray(),"UTF-8");}String original=new JSONObject(raw.replace("\uFEFF","")).getJSONObject("data").getJSONObject("document").getString("content");Matcher code=Pattern.compile("(?m)^```[^\\n]*\\n([\\s\\S]*?)\\n```(?:\\n|$)").matcher(original);int codes=0;while(code.find()){check(note.contains(code.group(1)),"Original code block "+(++codes)+" preserved byte-for-byte");}check(codes==16,"All sixteen original code blocks compared with independent Feishu document fetch");
  check(live.getJSONArray("warnings").toString().contains("whiteboard")&&note.contains("[未导入的飞书内容：whiteboard]"),"Embedded whiteboard is explicitly marked unsupported, never claimed imported");
  h.js("FeishuUI.preview("+live.toString()+")");until("!!document.querySelector('#feishu-save')");Thread.sleep(500);h.screenshot("feishu-second-preview.png");h.js("document.querySelector('#feishu-ack').checked=true;document.querySelector('#feishu-minutes').value=40;document.querySelector('#feishu-save').click()");until("document.querySelector('#editor').open&&!!document.querySelector('#doc-read')&&!document.querySelector('#doc-read').hidden");
  JSONObject saved=source(TOKEN);check(saved!=null&&saved.getString("note").equals(note)&&saved.getInt("durationMinutes")==40,"Second real note saved via preview with full original and independent duration");check(saved.getString("date").equals("2026-03-27"),"Second real note saves source creation date");check(source(firstToken).toString().equals(before),"Second import leaves first note completely unchanged");Thread.sleep(500);h.screenshot("feishu-second-reader.png");
  JSONObject reread=(JSONObject)h.call("feishuRead",new JSONObject().put("url",URL));check(reread.getBoolean("unchanged")&&reread.getJSONObject("existing").getString("id").equals(saved.getString("id")),"Re-reading second link deduplicates against its own document, not first note");FeishuImport.clear(getTargetContext(),reread.getString("ticket"));
  result.putString("stream","PASS Second real document "+passed+" checks\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable ex){StringBuilder causes=new StringBuilder();for(Throwable t=ex;t!=null;t=t.getCause())causes.append(t).append('\n');result.putString("stream","FAIL Second Feishu document: "+causes+android.util.Log.getStackTraceString(ex));finish(Activity.RESULT_CANCELED,result);}}
}
